SELECT gen_random_uuid()::text, e."id", v."date"::timestamp, 'DIARIO'::"PeriodType", 'IMPORTADO'::"SalesEntrySource", v."faturamentoDelivery", v."faturamentoSalao", v."pedidosDelivery"::int, v."pedidosBalcao"::int, v."pedidosSalao"::int, v."taxaServicoValor", v."observacoes", NULL, now(), now()
